#include <stddef.h>
#include <stdint.h>
#define MAX_WORDS 32
#define MAX_WORD_LEN 8
#define MAX_INPUT 307
static int equal_word(const int64_t* v,size_t start,size_t length,size_t target,size_t target_length){if(length!=target_length)return 0;for(size_t i=0;i<length;i++)if(v[start+i]!=v[target+i])return 0;return 1;}
int64_t shortest_word_distance(const int64_t* v,size_t length){if(v==NULL||length<1||length>MAX_INPUT+1)return -1;if(v[0]<2||v[0]>MAX_WORDS)return -1;size_t n=(size_t)v[0],starts[MAX_WORDS],sizes[MAX_WORDS],p=1;for(size_t i=0;i<n;i++){if(p>=length)return -1;int64_t z=v[p++];if(z<1||z>MAX_WORD_LEN||p+(size_t)z>length)return -1;starts[i]=p;sizes[i]=(size_t)z;for(size_t j=0;j<(size_t)z;j++)if(!((v[p+j]>=65&&v[p+j]<=90)||(v[p+j]>=97&&v[p+j]<=122)))return -1;p+=(size_t)z;}size_t target_start[2],target_size[2];for(size_t t=0;t<2;t++){if(p>=length)return -1;int64_t z=v[p++];if(z<1||z>MAX_WORD_LEN||p+(size_t)z>length)return -1;target_start[t]=p;target_size[t]=(size_t)z;for(size_t j=0;j<(size_t)z;j++)if(!((v[p+j]>=65&&v[p+j]<=90)||(v[p+j]>=97&&v[p+j]<=122)))return -1;p+=(size_t)z;}if(p!=length||equal_word(v,target_start[0],target_size[0],target_start[1],target_size[1]))return -1;int have0=0,have1=0;size_t best=n;for(size_t i=0;i<n;i++){int a=equal_word(v,starts[i],sizes[i],target_start[0],target_size[0]);int b=equal_word(v,starts[i],sizes[i],target_start[1],target_size[1]);have0|=a;have1|=b;for(size_t j=0;j<n;j++){int c=equal_word(v,starts[j],sizes[j],target_start[0],target_size[0]);int d=equal_word(v,starts[j],sizes[j],target_start[1],target_size[1]);if((a&&d)||(b&&c)){size_t delta=i>j?i-j:j-i;if(delta<best)best=delta;}}}if(!have0||!have1)return -1;return (int64_t)best;}
